window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-developer-webhook.html"]="<!-- Settings: Webhooks -->\n<style>\n.wh-empty{text-align:center;padding:40px;color:var(--muted)}\n.badge{display:inline-block;padding:3px 10px;border-radius:10px;font-size:11px;font-weight:700}\n.badge.ok{background:#dcfce7;color:#15803d}.badge.err{background:#fef2f2;color:var(--danger)}\n.wh-events{display:flex;flex-wrap:wrap;gap:6px;margin-top:2px}\n.wh-event-tag{padding:2px 8px;border-radius:8px;font-size:11px;background:var(--bg);border:1px solid var(--border)}\n.st-form label{display:block;font-size:13px;font-weight:500;margin-bottom:14px}\n.st-form label input{display:block;width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:8px;margin-top:4px;font-size:14px;background:var(--bg)}\n.st-form label input:focus{outline:2px solid var(--accent);outline-offset:-1px}\n.wh-ev-checks{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:14px}\n.wh-ev-checks label{display:flex;align-items:center;gap:6px;font-size:13px;font-weight:400;cursor:pointer}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">Role & Izin</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">Makro</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-tickets')\">Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/developer-webhook')\">Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <div style=\"display:flex;align-items:center;gap:12px;margin-bottom:20px\">\n      <h2 style=\"flex:1\">Webhook</h2>\n      <button class=\"btn primary\" onclick=\"openWhForm()\">+ Tambah Webhook</button>\n    </div>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:16px\">Atur URL endpoint yang akan menerima notifikasi event dari SatuInbox.</p>\n\n    <table class=\"data-table\" id=\"whTable\">\n      <thead><tr><th>URL</th><th>Event</th><th>Status</th><th></th></tr></thead>\n      <tbody id=\"whBody\"></tbody>\n    </table>\n  </div>\n</div>\n\n<!-- Add/Edit Modal -->\n<div class=\"modal-overlay\" id=\"whModal\">\n  <div class=\"modal\" style=\"max-width:520px\">\n    <h3 id=\"whModalTitle\">Tambah Webhook</h3>\n    <div class=\"st-form\">\n      <label>URL Endpoint<input id=\"whUrl\" placeholder=\"https://example.com/webhook\"></label>\n      <div style=\"font-size:13px;font-weight:500;margin-bottom:8px\">Event yang dipantau:</div>\n      <div class=\"wh-ev-checks\" id=\"whEventChecks\"></div>\n    </div>\n    <div class=\"modal-actions\" style=\"display:flex;gap:8px;justify-content:flex-end;margin-top:16px\">\n      <button class=\"btn\" onclick=\"closeModal('whModal')\">Batal</button>\n      <button class=\"btn primary\" onclick=\"saveWh()\">Simpan</button>\n    </div>\n  </div>\n</div>\n\n<!-- Delete Confirm -->\n<div class=\"modal-overlay\" id=\"whDelModal\">\n  <div class=\"modal\" style=\"max-width:400px\">\n    <h3>Hapus Webhook</h3>\n    <p style=\"font-size:13px;color:var(--muted);margin:12px 0\">Yakin ingin menghapus webhook ini?</p>\n    <div class=\"modal-actions\" style=\"display:flex;gap:8px;justify-content:flex-end\">\n      <button class=\"btn\" onclick=\"closeModal('whDelModal')\">Batal</button>\n      <button class=\"btn danger\" onclick=\"confirmDelWh()\">Hapus</button>\n    </div>\n  </div>\n</div>\n\n<script>\nvar WH_EVENTS=['message.incoming','message.sent','conversation.created','conversation.closed','ticket.created','ticket.resolved','lead.created'];\nvar whEditId=null,whDelId=null;\n\nfunction renderWebhooks(){\n  const list=DB.settings.webhooks||[];\n  const tbody=document.getElementById('whBody');\n  if(!list.length){tbody.innerHTML='<tr><td colspan=\"4\" class=\"wh-empty\">Belum ada webhook</td></tr>';return}\n  tbody.innerHTML=list.map(w=>{\n    const evs=w.events.map(e=>'<span class=\"wh-event-tag\">'+e+'</span>').join('');\n    return '<tr>'\n      +'<td style=\"font-size:13px;word-break:break-all;max-width:300px\">'+w.url+'</td>'\n      +'<td><div class=\"wh-events\">'+evs+'</div></td>'\n      +'<td>'+(w.active?'<span class=\"badge ok\">Aktif</span>':'<span class=\"badge err\">Nonaktif</span>')+'</td>'\n      +'<td style=\"white-space:nowrap\">'\n        +'<button class=\"btn\" style=\"padding:4px 10px;font-size:12px\" onclick=\"toggleWhActive(\\''+w.id+'\\')\">'+(w.active?'Nonaktif':'Aktif')+'</button> '\n        +'<button class=\"btn\" style=\"padding:4px 10px;font-size:12px\" onclick=\"editWh(\\''+w.id+'\\')\">✏️</button> '\n        +'<button class=\"btn danger\" style=\"padding:4px 10px;font-size:12px\" onclick=\"delWh(\\''+w.id+'\\')\">🗑️</button>'\n      +'</td></tr>';\n  }).join('');\n}\n\nfunction whCheckboxes(selected){\n  return WH_EVENTS.map(e=>{\n    const chk=(selected||[]).includes(e)?'checked':'';\n    return '<label><input type=\"checkbox\" value=\"'+e+'\" '+chk+'>'+e+'</label>';\n  }).join('');\n}\n\nfunction getCheckedEvents(){\n  return Array.from(document.querySelectorAll('#whEventChecks input:checked')).map(i=>i.value);\n}\n\nfunction openWhForm(id){\n  whEditId=id||null;\n  const w=id?(DB.settings.webhooks||[]).find(x=>x.id===id):null;\n  document.getElementById('whModalTitle').textContent=id?'Edit Webhook':'Tambah Webhook';\n  document.getElementById('whUrl').value=w?w.url:'';\n  document.getElementById('whEventChecks').innerHTML=whCheckboxes(w?w.events:[]);\n  document.getElementById('whModal').classList.add('open');\n}\n\nfunction editWh(id){openWhForm(id)}\n\nfunction saveWh(){\n  const url=document.getElementById('whUrl').value.trim();\n  const events=getCheckedEvents();\n  if(!url){showToast('URL wajib diisi');return}\n  if(!events.length){showToast('Pilih minimal satu event');return}\n  if(whEditId){\n    const i=DB.settings.webhooks.findIndex(w=>w.id===whEditId);\n    if(i>=0){DB.settings.webhooks[i]={...DB.settings.webhooks[i],url,events}}\n  }else{\n    DB.settings.webhooks.push({id:genId('wh'),url,events,active:true});\n  }\n  saveStore();\n  closeModal('whModal');\n  renderWebhooks();\n  showToast('Webhook berhasil disimpan');\n}\n\nfunction delWh(id){whDelId=id;document.getElementById('whDelModal').classList.add('open')}\nfunction confirmDelWh(){\n  DB.settings.webhooks=DB.settings.webhooks.filter(w=>w.id!==whDelId);\n  saveStore();closeModal('whDelModal');renderWebhooks();showToast('Webhook dihapus');\n}\n\nfunction toggleWhActive(id){\n  const w=DB.settings.webhooks.find(x=>x.id===id);\n  if(w){w.active=!w.active;saveStore();renderWebhooks()}\n}\n\nfunction closeModal(id){document.getElementById(id).classList.remove('open')}\n\nrenderWebhooks();\n</script>\n";
